const FALLBACK_3DIAS = 'Olá, {{nomeCliente}}!\n\nSua mensalidade vence em 3 dias.\n\n💰 Valor: {{valorMensalidade}}\n📆 Vencimento: {{dataVencimento}}\n\n🔑 Chave Pix: {{chavePix}}\n\nEvite juros e multas, pague em dia!\n\n_{{nomeEmpresa}}_';

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let mensagem = data.template_mensagem;
  if (!mensagem || mensagem.trim() === '') {
    mensagem = FALLBACK_3DIAS;
  }

  const variaveis = {
    '{{nomeCliente}}': data.nome_cliente,
    '{{nomeAlunoReal}}': (data.nome_aluno_real || '').split(' ')[0],
    '{{nomeResponsavel}}': (data.nome_responsavel || '').split(' ')[0],
    '{{valorMensalidade}}': `R$ ${parseFloat(data.valor_em_aberto).toFixed(2)}`,
    '{{dataVencimento}}': new Date(data.data_vencimento).toLocaleDateString('pt-BR'),
    '{{diasRestantes}}': data.dias_restantes || 3,
    '{{nomeEmpresa}}': data.nome_empresa || 'Equipe',
    '{{chavePix}}': data.chave_pix || '',
    '{{linkPagamento}}': (data.metodo_pagamento === 'asaas_link' && data.portal_token) ? 'https://www.mensalli.com.br/portal/' + data.portal_token : ''
  };

  Object.entries(variaveis).forEach(([chave, valor]) => {
    mensagem = mensagem.replace(new RegExp(chave, 'g'), valor);
  });

  let telefone = String(data.telefone || '').replace(/\D/g, '');
  if (!telefone.startsWith('55')) telefone = '55' + telefone;

  results.push({
    json: {
      ...data,
      mensagem,
      telefone,
      evolution_url: `http://service-evolution-api:8080/message/sendText/${data.evolution_instance_name}`,
      tipo_lembrete: '3dias_antes',
      flag_campo: 'enviado_3dias'
    }
  });
}

return results;

