// Compara numeros, nao strings. Em DDD de celular pre-2014 o JID canonico do
// WhatsApp NAO tem o nono digito, entao a Evolution roteia para a grafia sem
// ele — isso e o comportamento CORRETO, nao erro. Comparar como texto marcava
// entrega boa como falha, a parcela nao era marcada e o aluno recebia de novo
// a cada execucao: em 13/08, 4 alunos receberam a mesma cobranca duas vezes
// (tres deles ja tinham LIDO a primeira).
const _soNum = (j) => String(j || '').split('@')[0].replace(/\D/g, '');
const _norm = (j) => {
  let n = _soNum(j);
  if (n.startsWith('55')) n = n.slice(2);
  if (n.length === 11 && n[2] === '9') n = n.slice(0, 2) + n.slice(3);
  return n;
};

